// Shared TEST-ONLY harness for opt-in real-mount checks: a stand-in backend (grant-scoped metadata
// routes), the real agent started through FixtureAgentMain (fixture provider, generated bytes),
// Electron's part (cache session, mount, credential pump) and the real VFS. Nothing here contacts
// Google, Dropbox or the real backend; results are fixture evidence, never live verification.
import { spawn } from 'node:child_process';
import { createHash, randomBytes } from 'node:crypto';
import { createServer } from 'node:http';
import { existsSync, mkdtempSync, readFileSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

export const MiB = 1024 * 1024;
export const GiB = 1024 * MiB;
export const BOX = '11111111-2222-4333-8444-555555555555';
export const DRIVE = '66666666-7777-4888-9999-aaaaaaaaaaaa';
export const USER = '22222222-3333-4444-8555-666666666666';

/** The fixture byte at position p (mirrors FixtureAgentMain.gen). */
export const gen = (seed, p) => {
  const lo = p % 4294967296;
  const hi = Math.floor(p / 4294967296);
  return (lo * 7 + hi * 13 + Math.floor(lo / 2048) + seed) % 256;
};
export const expected = (seed, offset, length) => {
  const b = Buffer.allocUnsafe(length);
  for (let i = 0; i < length; i++) b[i] = gen(seed, offset + i);
  return b;
};
export const sha = (b) => createHash('sha256').update(b).digest('hex');

export function checker() {
  const results = [];
  const check = (name, ok, detail = '') => {
    results.push(ok);
    console.log(`${ok ? 'PASS' : 'FAIL'} ${name}${detail ? ` (${detail})` : ''}`);
    return ok;
  };
  return { results, check, failed: () => results.filter((ok) => !ok).length };
}

/** Stand-in backend. `missing` ids are listed but their metadata route answers 404 (deleted remotely). */
export async function startBackend(files, { missing = [] } = {}) {
  const grant = `hdm_${randomBytes(32).toString('base64url')}`;
  const requests = [];
  const sockets = new Set();
  const server = createServer((req, res) => {
    const okAuth = req.headers.authorization === `Bearer ${grant}`;
    requests.push(`${req.method} ${req.url} ${okAuth ? 'grant-ok' : 'bad-auth'}`);
    const json = (status, body) => res.writeHead(status, { 'content-type': 'application/json' }).end(JSON.stringify(body));
    if (!okAuth) return json(401, { code: 'unauthenticated' });
    const url = new URL(req.url, 'http://127.0.0.1');
    if (url.pathname === '/api/v1/vfs/accounts') {
      return json(200, { items: [
        { id: BOX, provider: 'DROPBOX', rootType: 'USER', status: 'CONNECTED' },
        { id: DRIVE, provider: 'GOOGLE_DRIVE', rootType: 'USER', status: 'CONNECTED' }
      ] });
    }
    const list = /^\/api\/v1\/vfs\/accounts\/([0-9a-f-]{36})\/files$/.exec(url.pathname);
    if (list) {
      const items = files.filter((f) => f.account === list[1]).map((f) => ({
        id: f.id, name: f.name, kind: 'FILE', sizeBytes: f.size, modifiedAt: '2026-11-01T10:00:00Z', directoryLocator: null
      }));
      return json(200, { items, continuation: null });
    }
    const one = /^\/api\/v1\/vfs\/accounts\/([0-9a-f-]{36})\/files\/(.+)$/.exec(url.pathname);
    if (one) {
      const id = decodeURIComponent(one[2]);
      const f = files.find((x) => x.account === one[1] && x.id === id);
      if (!f || missing.includes(id)) return json(404, { code: 'file_not_found' });
      return json(200, { id: f.id, provider: f.provider, kind: 'FILE', sizeBytes: f.size, modifiedAt: '2026-11-01T10:00:00Z', providerRevision: f.rev, canDownload: true });
    }
    return json(404, { code: 'not_found' });
  });
  server.on('connection', (s) => {
    sockets.add(s);
    s.on('close', () => sockets.delete(s));
  });
  await new Promise((r) => server.listen(0, '127.0.0.1', r));
  const port = server.address().port;
  return {
    grant,
    requests,
    origin: `http://127.0.0.1:${port}`,
    /** Simulates a backend outage: stops listening and drops open connections. */
    stop: () => new Promise((r) => { server.close(() => r()); for (const s of sockets) s.destroy(); }),
    restart: () => new Promise((r) => server.listen(port, '127.0.0.1', r))
  };
}

/** The real agent via its TEST-ONLY fixture entry point. */
export async function startAgent(agentDir, files, tokens, { dataDir } = {}) {
  const work = mkdtempSync(join(tmpdir(), 'hd-fixture-'));
  const specPath = join(work, 'fixture-spec.json');
  writeFileSync(specPath, JSON.stringify({
    googleToken: tokens.google, dropboxToken: tokens.dropbox, dropboxRootNamespace: '777',
    files: files.map(({ id, provider, size, seed, rev, delayMs, source }) => ({ id, provider, size, seed: seed ?? 0, rev, delayMs: delayMs ?? 0, ...(source ? { source } : {}) }))
  }));
  const classpath = [join(agentDir, 'target', 'classes'), join(agentDir, 'target', 'test-classes'),
    readFileSync(join(agentDir, 'target', 'fixture-classpath.txt'), 'utf8').trim()].join(';');
  const secret = randomBytes(32).toString('base64url');
  const proc = spawn(process.env.JAVA_HOME ? join(process.env.JAVA_HOME, 'bin', 'java.exe') : 'java', ['-cp', classpath, 'com.hyperdrive.agent.FixtureAgentMain', specPath], { stdio: ['pipe', 'pipe', 'pipe'], windowsHide: true });
  const agent = { proc, work, secret, err: '', exited: new Promise((r) => proc.on('exit', r)) };
  proc.stderr.on('data', (c) => (agent.err += c));
  proc.stdin.write(`${JSON.stringify({ protocolVersion: 1, secret, dataDir: dataDir ?? join(work, 'agent'), logLevel: 'INFO', requestTimeoutMs: 30000 })}\n`);
  agent.port = await new Promise((r, j) => {
    let out = '';
    proc.stdout.on('data', (c) => {
      out += c;
      const nl = out.indexOf('\n');
      if (nl >= 0) r(JSON.parse(out.slice(0, nl)).port);
    });
    setTimeout(() => j(new Error(`agent handshake timeout: ${agent.err}`)), 30000);
  });
  const m = /provider control port (\d+)/.exec(agent.err);
  agent.providerPort = m ? Number(m[1]) : null;
  agent.call = (method, path, body, timeoutMs = 35000) => fetch(`http://127.0.0.1:${agent.port}${path}`, {
    method,
    headers: { Authorization: `Bearer ${secret}`, ...(body ? { 'Content-Type': 'application/json' } : {}) },
    body: body ? JSON.stringify(body) : undefined,
    signal: AbortSignal.timeout(timeoutMs)
  }).then(async (r) => ({ status: r.status, body: await r.json() }));
  agent.admin = (path, body, t) => agent.call('POST', path, body, t);
  agent.stats = async () => (await agent.call('GET', '/local/v1/vfs/status')).body.reads;
  agent.network = (state) => fetch(`http://127.0.0.1:${agent.providerPort}/fixture/network?state=${state}`).then((r) => r.json());
  return agent;
}

/**
 * Electron main's part: mount + credential pump. `expiresIn(accountId, n)` chooses the provider
 * expiry (seconds) of the n-th credential installed for an account (default 1 h).
 */
export async function mountAndPump(agent, backend, tokens, { expiresIn = () => 3600 } = {}) {
  const mount = await agent.admin('/local/v1/vfs/mount', { userId: USER, backendOrigin: backend.origin, grant: backend.grant, grantExpiresAt: new Date(Date.now() + 600_000).toISOString() });
  const state = { generation: mount.body.generation, capability: mount.body.capability, pumping: true, installs: [] };
  state.pump = (async () => {
    while (state.pumping) {
      let polled;
      try {
        polled = await agent.admin('/local/v1/vfs/credential-requests', { generation: state.generation }, 30000);
      } catch {
        await new Promise((r) => setTimeout(r, 200));
        continue;
      }
      if (polled.status !== 200) {
        await new Promise((r) => setTimeout(r, 200));
        continue;
      }
      for (const { accountId } of polled.body.requests) {
        const dropbox = accountId === BOX;
        const n = state.installs.filter((i) => i.accountId === accountId).length;
        const r = await agent.admin('/local/v1/vfs/mount/credential', {
          generation: state.generation, accountId, provider: dropbox ? 'DROPBOX' : 'GOOGLE_DRIVE', accessToken: dropbox ? tokens.dropbox : tokens.google,
          providerExpiresAt: new Date(Date.now() + expiresIn(accountId, n) * 1000).toISOString(), ...(dropbox ? { rootNamespaceId: '777' } : {})
        }).catch(() => ({ status: 0 }));
        state.installs.push({ accountId, status: r.status, at: Date.now() });
      }
    }
  })();
  return state;
}

export function freeLetter() {
  return [...'ZYXWVUTSRQPONMLKJI'].find((l) => !existsSync(`${l}:\\`));
}

/** The real VFS, normal mode. */
export function startVfs(exe, agentPort, capability, letter) {
  const proc = spawn(exe, [], { stdio: ['pipe', 'pipe', 'pipe'], windowsHide: true });
  const run = { proc, events: [], err: '', exitAt: null };
  proc.stderr.on('data', (c) => (run.err += c));
  run.exited = new Promise((r) => proc.on('exit', (code) => { run.exitAt = Date.now(); r(code); }));
  let buf = '';
  run.mounted = new Promise((r, j) => {
    proc.stdout.on('data', (c) => {
      buf += c;
      let nl;
      while ((nl = buf.indexOf('\n')) >= 0) {
        const e = JSON.parse(buf.slice(0, nl));
        buf = buf.slice(nl + 1);
        run.events.push(e);
        if (e.event === 'started') proc.stdin.write(`${JSON.stringify({ protocolVersion: 1, agentPort, capability, mount: { driveLetter: letter } })}\n`);
        if (e.event === 'mounted') r();
        if (e.event === 'failed') j(new Error(e.code));
      }
    });
    setTimeout(() => j(new Error('mount timeout')), 30000);
  });
  return run;
}

/** Working-set bytes of a process (PowerShell; no admin). */
export function workingSet(pid) {
  return new Promise((r) => {
    const p = spawn('powershell', ['-NoProfile', '-Command', `(Get-Process -Id ${pid} -ErrorAction SilentlyContinue).WorkingSet64`], { windowsHide: true });
    let out = '';
    p.stdout.on('data', (c) => (out += c));
    p.on('exit', () => r(Number(out.trim()) || null));
  });
}

export const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
